head.b:skin:
/*
-----------------------------------------------
Blogger Template: AIBoostsLab
Brand: AIBoostsLab - Boost Your Future With AI
Designer-ready AI SaaS style Blogger XML theme
----------------------------------------------- */
:root{
  --primary:#1769ff;
  --primary-2:#00b7ff;
  --primary-dark:#0f46b8;
  --bg:#f5f8ff;
  --surface:#ffffff;
  --surface-2:#eef5ff;
  --text:#0d1b3d;
  --muted:#667391;
  --line:#dce7fb;
  --shadow:0 20px 60px rgba(17,73,169,.12);
  --radius:22px;
  --max:1180px;
  --header-h:76px;
}
html{scroll-behavior:smooth}
*{box-sizing:border-box}
body{
  margin:0;
  color:var(--text);
  background:radial-gradient(circle at top left,rgba(23,105,255,.14),transparent 34rem),linear-gradient(180deg,#fff 0%,var(--bg) 42%,#fff 100%);
  font-family:Inter,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Arial,sans-serif;
  font-size:16px;
  line-height:1.65;
  overflow-x:hidden;
}
body.dark-mode{
  --bg:#071126;
  --surface:#0d1b35;
  --surface-2:#10254a;
  --text:#eef5ff;
  --muted:#b7c5e5;
  --line:#213a66;
  --shadow:0 20px 60px rgba(0,0,0,.35);
  background:radial-gradient(circle at top left,rgba(0,183,255,.16),transparent 34rem),linear-gradient(180deg,#091733 0%,#071126 100%);
}
a{color:var(--primary);text-decoration:none;transition:.2s ease}
a:hover{color:var(--primary-dark)}
img{height:auto;max-width:100%;display:block}
.container{width:min(var(--max),calc(100% - 32px));margin-inline:auto}
.skip-link{position:absolute;left:-999px;top:auto;background:var(--primary);color:#fff;padding:10px 16px;border-radius:10px;z-index:10000}
.skip-link:focus{left:16px;top:16px}
.site-header{position:sticky;top:0;z-index:999;background:rgba(255,255,255,.86);backdrop-filter:blur(18px);border-bottom:1px solid var(--line)}
.dark-mode .site-header{background:rgba(7,17,38,.86)}
.header-inner{height:var(--header-h);display:flex;align-items:center;justify-content:space-between;gap:20px}
.brand{display:flex;align-items:center;gap:12px;color:var(--text)}
.brand-mark{width:44px;height:44px;border-radius:14px;background:linear-gradient(135deg,var(--primary),var(--primary-2));display:grid;place-items:center;color:#fff;font-weight:900;box-shadow:0 10px 30px rgba(23,105,255,.3)}
.brand-name{font-size:1.35rem;font-weight:900;letter-spacing:-.04em;display:block;line-height:1}
.brand-tagline{font-size:.78rem;color:var(--muted);display:block;margin-top:4px}
.nav-wrap{display:flex;align-items:center;gap:16px}
#menu-toggle{display:none}
.nav-toggle{display:none;width:42px;height:42px;border:1px solid var(--line);border-radius:14px;background:var(--surface);cursor:pointer;place-items:center}
.nav-toggle span,.nav-toggle span:before,.nav-toggle span:after{display:block;width:18px;height:2px;background:var(--text);border-radius:4px;content:"";position:relative}
.nav-toggle span:before{position:absolute;top:-6px}.nav-toggle span:after{position:absolute;top:6px}
.menu-section .widget{margin:0}.menu-section ul{list-style:none;padding:0;margin:0;display:flex;align-items:center;gap:4px}.menu-section li a{display:block;padding:10px 12px;border-radius:12px;color:var(--text);font-weight:700;font-size:.94rem}.menu-section li a:hover{background:var(--surface-2);color:var(--primary)}
.theme-toggle{border:1px solid var(--line);background:var(--surface);color:var(--text);border-radius:999px;padding:10px 14px;cursor:pointer;font-weight:800;box-shadow:0 8px 20px rgba(23,105,255,.08)}
.hero{padding:72px 0 34px}.hero-grid{display:grid;grid-template-columns:minmax(0,1.08fr) minmax(280px,.92fr);gap:42px;align-items:center}.eyebrow{display:inline-flex;align-items:center;gap:8px;padding:8px 12px;background:var(--surface-2);color:var(--primary);border:1px solid var(--line);border-radius:999px;font-size:.82rem;font-weight:900;text-transform:uppercase;letter-spacing:.06em}.hero h1{font-size:clamp(2.4rem,6vw,5rem);line-height:.96;letter-spacing:-.075em;margin:18px 0;color:var(--text)}.gradient-text{background:linear-gradient(135deg,var(--primary),var(--primary-2));-webkit-background-clip:text;background-clip:text;color:transparent}.hero p{color:var(--muted);font-size:1.12rem;max-width:650px}.hero-actions{display:flex;flex-wrap:wrap;gap:14px;margin-top:28px}.btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;border-radius:999px;padding:13px 20px;font-weight:900;border:1px solid var(--line)}.btn-primary{background:linear-gradient(135deg,var(--primary),var(--primary-2));color:#fff;box-shadow:0 16px 36px rgba(23,105,255,.28)}.btn-primary:hover{color:#fff;transform:translateY(-2px)}.btn-ghost{background:var(--surface);color:var(--text)}
.hero-card{background:linear-gradient(180deg,rgba(255,255,255,.88),rgba(238,245,255,.86));border:1px solid var(--line);border-radius:32px;padding:22px;box-shadow:var(--shadow);position:relative;overflow:hidden}.dark-mode .hero-card{background:linear-gradient(180deg,rgba(13,27,53,.92),rgba(16,37,74,.86))}.hero-card:before{content:"";position:absolute;inset:-40% -30% auto auto;width:220px;height:220px;border-radius:50%;background:rgba(0,183,255,.22)}.metric-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px;position:relative}.metric{background:var(--surface);border:1px solid var(--line);border-radius:20px;padding:18px}.metric strong{display:block;font-size:1.9rem;line-height:1;color:var(--primary)}.metric span{font-size:.86rem;color:var(--muted);font-weight:700}.ai-terminal{position:relative;margin-top:14px;background:#081328;color:#dbeafe;border-radius:20px;padding:18px;font-family:"SFMono-Regular",Consolas,monospace;font-size:.9rem;box-shadow:inset 0 0 0 1px rgba(255,255,255,.08)}.dot{display:inline-block;width:10px;height:10px;border-radius:50%;background:#2ee59d;margin-right:6px}.dot:nth-child(2){background:#ffd166}.dot:nth-child(3){background:#ff5c8a}.code-line{margin-top:14px;color:#93c5fd}.code-line em{color:#67e8f9;font-style:normal}
.ad-slot{min-height:90px;border:1px dashed #9bbcff;border-radius:18px;background:linear-gradient(135deg,rgba(23,105,255,.06),rgba(0,183,255,.06));display:grid;place-items:center;color:var(--muted);font-size:.85rem;font-weight:800;text-align:center;padding:16px;margin:28px 0}.ad-sidebar{min-height:280px}.ad-inpost{min-height:120px}
.section-title{display:flex;align-items:end;justify-content:space-between;gap:16px;margin:34px 0 18px}.section-title h2{margin:0;font-size:clamp(1.7rem,3vw,2.45rem);letter-spacing:-.05em}.section-title p{margin:0;color:var(--muted)}
.featured-slider{position:relative;overflow:hidden;border-radius:30px;border:1px solid var(--line);background:var(--surface);box-shadow:var(--shadow)}.slider-track{display:flex;transition:transform .5s ease}.slide{min-width:100%;display:grid;grid-template-columns:1fr 1fr;gap:0;align-items:stretch}.slide-media{min-height:320px;background:linear-gradient(135deg,var(--primary),var(--primary-2));display:grid;place-items:center;color:#fff;font-size:4rem}.slide-content{padding:38px}.slide-content h3{font-size:clamp(1.7rem,3vw,2.5rem);line-height:1.08;margin:10px 0;letter-spacing:-.05em}.slide-content p{color:var(--muted)}.slider-dots{position:absolute;left:38px;bottom:28px;display:flex;gap:8px}.slider-dot{width:10px;height:10px;border-radius:999px;border:0;background:#b9cdf6;cursor:pointer}.slider-dot.active{width:28px;background:var(--primary)}
.layout{display:grid;grid-template-columns:minmax(0,1fr) 330px;gap:32px;align-items:start;padding:34px 0 56px}.content-card,.sidebar .widget,.footer-widget,.newsletter{background:var(--surface);border:1px solid var(--line);border-radius:var(--radius);box-shadow:var(--shadow)}.main-section .widget{margin:0}.blog-posts{display:grid;gap:24px}.post-outer,.date-outer{margin:0}.post,.entry{background:var(--surface);border:1px solid var(--line);border-radius:var(--radius);box-shadow:var(--shadow);padding:28px;margin:0 0 24px}.post-title,.entry-title{font-size:clamp(1.6rem,3vw,2.35rem);line-height:1.12;letter-spacing:-.045em;margin:0 0 12px}.post-title a{color:var(--text)}.post-title a:hover{color:var(--primary)}.post-header,.post-meta{color:var(--muted);font-size:.9rem;margin-bottom:16px}.post-body{color:var(--text)}.post-body h2,.post-body h3{letter-spacing:-.035em;line-height:1.2}.post-body blockquote{border-left:4px solid var(--primary);background:var(--surface-2);margin:24px 0;padding:18px 22px;border-radius:0 16px 16px 0}.post-body pre{overflow:auto;background:#071126;color:#dbeafe;padding:18px;border-radius:18px}.post-footer{border-top:1px solid var(--line);margin-top:22px;padding-top:18px;color:var(--muted)}
.share-box,.related-posts{margin-top:24px;padding:22px;background:var(--surface);border:1px solid var(--line);border-radius:var(--radius)}.share-buttons{display:flex;flex-wrap:wrap;gap:10px}.share-buttons a{padding:10px 12px;border-radius:12px;color:#fff;font-weight:800;font-size:.9rem}.share-x{background:#111827}.share-facebook{background:#1877f2}.share-linkedin{background:#0a66c2}.share-pinterest{background:#e60023}.related-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}.related-card{padding:16px;border:1px solid var(--line);border-radius:16px;background:var(--surface-2);font-weight:800;color:var(--text)}
.sidebar{position:sticky;top:calc(var(--header-h) + 20px);display:grid;gap:20px}.sidebar .widget{padding:22px}.sidebar .widget-title,.sidebar h2,.footer h2{font-size:1.1rem;margin:0 0 14px;letter-spacing:-.02em}.sidebar ul,.footer ul{list-style:none;margin:0;padding:0}.sidebar li{border-bottom:1px solid var(--line);padding:10px 0}.sidebar li:last-child{border-bottom:0}.sidebar a{color:var(--text);font-weight:700}.sidebar a:hover{color:var(--primary)}
.newsletter{padding:32px;margin:24px 0;background:linear-gradient(135deg,var(--primary),var(--primary-2));color:#fff;overflow:hidden;position:relative}.newsletter:after{content:"";position:absolute;right:-80px;top:-80px;width:220px;height:220px;background:rgba(255,255,255,.18);border-radius:50%}.newsletter-inner{position:relative;display:grid;grid-template-columns:1fr auto;gap:24px;align-items:center}.newsletter h2{margin:0 0 8px;font-size:clamp(1.7rem,3vw,2.4rem);letter-spacing:-.05em}.newsletter p{margin:0;color:rgba(255,255,255,.86)}.newsletter-form{display:flex;gap:10px;background:rgba(255,255,255,.16);padding:8px;border-radius:999px;backdrop-filter:blur(8px)}.newsletter-form input{border:0;outline:0;background:#fff;color:#0d1b3d;border-radius:999px;padding:13px 16px;min-width:240px}.newsletter-form button{border:0;border-radius:999px;background:#071126;color:#fff;font-weight:900;padding:13px 18px;cursor:pointer}
.footer{background:#071126;color:#dbeafe;padding:52px 0 24px}.footer a{color:#dbeafe}.footer a:hover{color:#67e8f9}.footer-grid{display:grid;grid-template-columns:1.4fr repeat(3,1fr);gap:24px}.footer-widget{background:rgba(255,255,255,.06);border-color:rgba(255,255,255,.12);box-shadow:none;padding:22px}.footer-brand{font-size:1.5rem;font-weight:900;color:#fff}.copyright{border-top:1px solid rgba(255,255,255,.12);margin-top:28px;padding-top:20px;color:#9fb2d7;font-size:.9rem;display:flex;justify-content:space-between;gap:16px;flex-wrap:wrap}
.status-msg-wrap,.blog-pager{background:var(--surface);border:1px solid var(--line);border-radius:18px;padding:16px;margin:18px 0;text-align:center}.blog-pager a{display:inline-flex;margin:4px;padding:10px 14px;border-radius:999px;background:var(--surface-2);font-weight:900}.comments{background:var(--surface);border:1px solid var(--line);border-radius:var(--radius);padding:24px;margin-top:24px}.hidden{display:none!important}
@media (max-width: 980px){.hero-grid,.layout,.slide,.newsletter-inner,.footer-grid{grid-template-columns:1fr}.sidebar{position:static}.slide-media{min-height:220px}.newsletter-form{width:100%}.newsletter-form input{min-width:0;flex:1}}
@media (max-width: 760px){:root{--header-h:68px}.container{width:min(100% - 24px,var(--max))}.header-inner{gap:10px}.brand-mark{width:40px;height:40px}.brand-name{font-size:1.12rem}.brand-tagline{display:none}.nav-toggle{display:grid}.nav-wrap{gap:8px}.menu-section{position:absolute;left:12px;right:12px;top:calc(var(--header-h) + 10px);background:var(--surface);border:1px solid var(--line);border-radius:20px;box-shadow:var(--shadow);padding:10px;display:none}.menu-section ul{display:grid;gap:2px}.menu-section li a{padding:12px 14px}#menu-toggle:checked ~ .menu-section{display:block}.theme-toggle{padding:10px 12px}.hero{padding:42px 0 24px}.hero-actions{display:grid}.btn{width:100%}.metric-grid{grid-template-columns:1fr}.slide-content{padding:26px 22px 60px}.slider-dots{left:22px;bottom:20px}.post,.entry{padding:20px}.related-grid{grid-template-columns:1fr}.newsletter{padding:24px}.newsletter-form{border-radius:22px;display:grid}.newsletter-form input,.newsletter-form button{width:100%}.footer{padding-top:34px}.copyright{display:block}.copyright span{display:block;margin-top:8px}}
@media (prefers-reduced-motion: reduce){*{animation:none!important;transition:none!important;scroll-behavior:auto!important}}

body.script:
(function(){
  'use strict';
  var body=document.body;
  var toggle=document.getElementById('darkModeToggle');
  var saved='';
  try{saved=localStorage.getItem('aiboostslab-theme')||'';}catch(e){}
  if(saved==='dark'){body.classList.add('dark-mode');if(toggle){toggle.textContent='☀';}}
  if(toggle){toggle.addEventListener('click',function(){
    body.classList.toggle('dark-mode');
    var isDark=body.classList.contains('dark-mode');
    toggle.textContent=isDark?'☀':'☾';
    try{localStorage.setItem('aiboostslab-theme',isDark?'dark':'light');}catch(e){}
  });}

  var year=document.getElementById('yearNow');
  if(year){year.textContent=new Date().getFullYear();}

  var slider=document.getElementById('featuredSlider');
  if(slider){
    var track=slider.querySelector('.slider-track');
    var slides=slider.querySelectorAll('.slide');
    var dotsWrap=slider.querySelector('.slider-dots');
    var index=0;
    function go(i){
      index=(i+slides.length)%slides.length;
      track.style.transform='translateX(-'+(index*100)+'%)';
      var dots=dotsWrap.querySelectorAll('.slider-dot');
      for(var d=0;d<dots.length;d++){dots[d].classList.toggle('active',d===index);}
    }
    for(var i=0;i<slides.length;i++){
      var btn=document.createElement('button');
      btn.className='slider-dot'+(i===0?' active':'');
      btn.type='button';
      btn.setAttribute('aria-label','Go to featured slide '+(i+1));
      (function(n){btn.addEventListener('click',function(){go(n);});})(i);
      dotsWrap.appendChild(btn);
    }
    setInterval(function(){go(index+1);},6000);
  }

  var shareLinks=document.querySelectorAll('[data-share]');
  var pageUrl=encodeURIComponent(window.location.href);
  var pageTitle=encodeURIComponent(document.title);
  for(var s=0;s<shareLinks.length;s++){
    var network=shareLinks[s].getAttribute('data-share');
    var url='#';
    if(network==='x'){url='https://twitter.com/intent/tweet?url='+pageUrl+'&text='+pageTitle;}
    if(network==='facebook'){url='https://www.facebook.com/sharer/sharer.php?u='+pageUrl;}
    if(network==='linkedin'){url='https://www.linkedin.com/sharing/share-offsite/?url='+pageUrl;}
    if(network==='pinterest'){url='https://pinterest.com/pin/create/button/?url='+pageUrl+'&description='+pageTitle;}
    shareLinks[s].href=url;
  }
})();
